namespace {

void check_cusolver(cusolverStatus_t status, const char* what) {
    TORCH_CHECK(status == CUSOLVER_STATUS_SUCCESS, what, " failed with status ",
                static_cast<int>(status));
}

} // namespace

torch::Tensor direct_cholesky(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(input.scalar_type() == at::kFloat, "input must be float32");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(input.dim() == 3 && input.size(1) == input.size(2),
                "input must be a batch of square matrices");

    const int batch = static_cast<int>(input.size(0));
    const int n = static_cast<int>(input.size(1));
    const int64_t matrix_stride = static_cast<int64_t>(n) * n;

    // Keep the result row-major. cuSOLVER sees the same symmetric bytes as a
    // column-major matrix; factoring its upper triangle therefore appears as
    // the desired lower-triangular factor in the row-major Torch view.
    auto output = input.clone(at::MemoryFormat::Contiguous);
    auto info = at::empty({batch}, input.options().dtype(at::kInt));
    auto handle = at::cuda::getCurrentCUDASolverDnHandle();

    if (batch > 1) {
        const auto start = reinterpret_cast<int64_t>(output.data_ptr<float>());
        const auto step = matrix_stride * static_cast<int64_t>(sizeof(float));
        auto pointers = at::arange(
            start, start + static_cast<int64_t>(batch) * step, step,
            input.options().dtype(at::kLong));
        check_cusolver(
            cusolverDnSpotrfBatched(
                handle, CUBLAS_FILL_MODE_UPPER, n,
                reinterpret_cast<float**>(pointers.data_ptr<int64_t>()), n,
                info.data_ptr<int>(), batch),
            "cusolverDnSpotrfBatched");
    } else {
        int lwork = 0;
        check_cusolver(
            cusolverDnSpotrf_bufferSize(
                handle, CUBLAS_FILL_MODE_UPPER, n, output.data_ptr<float>(), n,
                &lwork),
            "cusolverDnSpotrf_bufferSize");
        auto workspace = at::empty({lwork}, input.options());
