import os

import torch
from torch.utils.cpp_extension import load_inline

from task import input_t, output_t


_CPP = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContextLight.h>
#include <cublas_v2.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_runtime_api.h>
#include <cusolverDn.h>

namespace {

void check_cusolver(cusolverStatus_t status, const char* what) {
    TORCH_CHECK(status == CUSOLVER_STATUS_SUCCESS, what, " failed with status ",
                static_cast<int>(status));
}

void check_cuda(cudaError_t status, const char* what) {
    TORCH_CHECK(status == cudaSuccess, what, " failed: ",
                cudaGetErrorString(status));
}

struct ParallelPotrfState {
    bool initialized = false;
    cudaStream_t streams[8]{};
    cusolverDnHandle_t handles[8]{};
    cudaEvent_t ready{};
    cudaEvent_t done[8]{};

    void initialize() {
        if (initialized) {
            return;
        }
        check_cuda(cudaEventCreateWithFlags(&ready, cudaEventDisableTiming),
                   "cudaEventCreate ready");
        for (int i = 0; i < 8; ++i) {
            check_cuda(cudaStreamCreateWithFlags(
                           &streams[i], cudaStreamNonBlocking),
                       "cudaStreamCreate");
            check_cusolver(cusolverDnCreate(&handles[i]),
                           "cusolverDnCreate");
            check_cusolver(cusolverDnSetStream(handles[i], streams[i]),
                           "cusolverDnSetStream");
            check_cuda(cudaEventCreateWithFlags(
                           &done[i], cudaEventDisableTiming),
                       "cudaEventCreate done");
        }
        initialized = true;
    }
};

ParallelPotrfState& parallel_state() {
    static auto* state = new ParallelPotrfState();
    state->initialize();
    return *state;
}

} // namespace

torch::Tensor direct_cholesky(
        torch::Tensor input,
        torch::Tensor output,
        torch::Tensor pointers,
        torch::Tensor info,
        torch::Tensor workspace) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(input.scalar_type() == at::kFloat, "input must be float32");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(input.dim() == 3 && input.size(1) == input.size(2),
                "input must be a batch of square matrices");
    TORCH_CHECK(output.is_cuda() && output.scalar_type() == at::kFloat,
                "output must be CUDA float32");
    TORCH_CHECK(output.is_contiguous() && output.sizes() == input.sizes(),
                "output must be a same-sized contiguous tensor");

    const int batch = static_cast<int>(input.size(0));
    const int n = static_cast<int>(input.size(1));
    // A raw contiguous clone is sufficient because the input is symmetric:
    // cuSOLVER can consume the same bytes as a column-major matrix.
    output.copy_(input);
    TORCH_CHECK(info.is_cuda() && info.scalar_type() == at::kInt &&
                info.numel() == batch, "invalid info tensor");
    auto handle = at::cuda::getCurrentCUDASolverDnHandle();

    const bool use_parallel = batch == 8 && n == 2048;
    const bool use_looped = batch <= 4 && n >= 1024;
    if (use_parallel) {
        TORCH_CHECK(workspace.is_cuda() &&
                    workspace.scalar_type() == at::kFloat &&
                    workspace.numel() % batch == 0,
                    "invalid parallel workspace tensor");
        const int lwork = workspace.numel() / batch;
        const int64_t matrix_stride = static_cast<int64_t>(n) * n;
        auto& state = parallel_state();
        cudaStream_t current = c10::cuda::getCurrentCUDAStream().stream();
        check_cuda(cudaEventRecord(state.ready, current),
                   "cudaEventRecord ready");
        for (int i = 0; i < batch; ++i) {
            check_cuda(cudaStreamWaitEvent(
                           state.streams[i], state.ready, 0),
                       "cudaStreamWaitEvent ready");
            check_cusolver(
                cusolverDnSpotrf(
                    state.handles[i], CUBLAS_FILL_MODE_LOWER, n,
                    output.data_ptr<float>() + i * matrix_stride, n,
                    workspace.data_ptr<float>() + i * lwork, lwork,
                    info.data_ptr<int>() + i),
                "parallel cusolverDnSpotrf");
            check_cuda(cudaEventRecord(state.done[i], state.streams[i]),
                       "cudaEventRecord done");
            check_cuda(cudaStreamWaitEvent(current, state.done[i], 0),
                       "cudaStreamWaitEvent done");
        }
    } else if (!use_looped) {
        TORCH_CHECK(pointers.is_cuda() &&
                    pointers.scalar_type() == at::kLong &&
                    pointers.numel() == batch, "invalid pointer array");
        check_cusolver(
            cusolverDnSpotrfBatched(
                handle, CUBLAS_FILL_MODE_LOWER, n,
                reinterpret_cast<float**>(pointers.data_ptr<int64_t>()), n,
                info.data_ptr<int>(), batch),
            "cusolverDnSpotrfBatched");
    } else {
        TORCH_CHECK(workspace.is_cuda() &&
                    workspace.scalar_type() == at::kFloat,
                    "invalid workspace tensor");
        const int64_t matrix_stride = static_cast<int64_t>(n) * n;
        for (int i = 0; i < batch; ++i) {
            check_cusolver(
                cusolverDnSpotrf(
                    handle, CUBLAS_FILL_MODE_LOWER, n,
                    output.data_ptr<float>() + i * matrix_stride, n,
                    workspace.data_ptr<float>(), workspace.numel(),
                    info.data_ptr<int>() + i),
                "cusolverDnSpotrf");
        }
    }

    // In the row-major view, cuSOLVER's column-major lower factor occupies the
    // upper triangle. Zero the other half and expose its transpose as an
    // F-contiguous lower-triangular Torch view without a data transpose.
    output.triu_();
    return output.transpose(-2, -1);
}

int64_t workspace_size(torch::Tensor input) {
    const int n = static_cast<int>(input.size(-1));
    int lwork = 0;
    check_cusolver(
        cusolverDnSpotrf_bufferSize(
            at::cuda::getCurrentCUDASolverDnHandle(),
            CUBLAS_FILL_MODE_LOWER, n, input.data_ptr<float>(), n, &lwork),
        "cusolverDnSpotrf_bufferSize");
    return lwork;
}
"""


_TORCH_LIB = os.path.join(os.path.dirname(torch.__file__), "lib")


_ext = load_inline(
    name="cholesky_direct_cusolver_v10",
    cpp_sources=_CPP,
    functions=["direct_cholesky", "workspace_size"],
    extra_cflags=["-O3"],
    extra_ldflags=[
