    ],
    with_cuda=True,
    verbose=False,
)


_active_shape = None
_output_cache = {}
_info = None
_workspace = None


def custom_kernel(data: input_t) -> output_t:
    global _active_shape, _info, _workspace
    if data.shape[-1] >= 256:
        shape = tuple(data.shape)
        if shape != _active_shape:
            _output_cache.clear()
            _active_shape = shape
